  const parsed = TicketInputSchema.safeParse(payload);
  if (parsed.success) return { success: true, data: parsed.data };
  return {
    success: false,
    issues: parsed.error.issues.map((issue) => ({
      field: issue.path.join(".") || "body",
      code: issue.code,
    })),
  };
}

